// core/config/__tests__/sec7-known-public-secrets.spec.ts · PC-56 SEC-7
// The repository is public: any value ever committed is known to an attacker. publicSecretProblems() (generated by
// scripts/security/known-public-secrets.mjs, one identical copy per backend service) names every env var whose secret
// — or connection-URL password — matches a fingerprint of a committed value. Production boot refuses on any match.
import { readFileSync } from 'fs';
import { resolve } from 'path';
import { randomBytes } from 'crypto';
import { publicSecretProblems, KNOWN_PUBLIC_SECRET_COUNT } from '../known-public-secrets.generated';

// Values that ARE in this repository's history (this file and app-config.security.spec.ts commit them).
const PUBLISHED = 'Zx9Qw7Vb3Nm2Kp5Lr8Td1Gh4Js6Fd0Ay2Bc7Xe';
const PUBLISHED_DB_PASSWORD = 'Str0ng-Db-Passw0rd-9x';
const fresh = () => randomBytes(32).toString('hex');

describe('SEC-7 · secrets committed to the public repository are refused', () => {
  it('carries fingerprints, never values', () => {
    expect(KNOWN_PUBLIC_SECRET_COUNT).toBeGreaterThan(100);
    const src = readFileSync(resolve(__dirname, '../known-public-secrets.generated.ts'), 'utf8');
    expect(src).not.toContain(PUBLISHED);
    expect(src).not.toContain(PUBLISHED_DB_PASSWORD);
  });

  it('names a secret-named variable that holds a published value', () => {
    expect(publicSecretProblems({ JWT_ACCESS_SECRET: PUBLISHED })).toEqual([
      expect.stringContaining('JWT_ACCESS_SECRET uses a value that was committed to the public repository'),
    ]);
  });

  it('finds a published password inside a connection URL, raw or percent-encoded', () => {
    const url = `postgresql://kv_app:${PUBLISHED_DB_PASSWORD}@db.example.com:5432/krishalaya`;
    expect(publicSecretProblems({ DATABASE_URL: url })).toHaveLength(1);
    const encoded = `postgresql://kv_app:${encodeURIComponent(PUBLISHED_DB_PASSWORD).replace(/-/g, '%2D')}@db.example.com:5432/k`;
    expect(publicSecretProblems({ DATABASE_URL: encoded })).toHaveLength(1);
  });

  it('accepts freshly generated secrets and ignores non-secret variables', () => {
    expect(publicSecretProblems({
      JWT_ACCESS_SECRET: fresh(),
      DATABASE_URL: `postgresql://kv_app:${fresh()}@db.example.com:5432/krishalaya`,
      // Not secret-named and not a URL with a password: never matched, even if the text is public.
      JWT_ISSUER: PUBLISHED,
      EMPTY_SECRET: '',
    })).toEqual([]);
  });

  it('is generated identically into all five backend services', () => {
    const root = resolve(__dirname, '../../../../../..');
    const copies = [
      'apps/api/src/core/config/known-public-secrets.generated.ts',
      'apps/admin-api/src/core/config/known-public-secrets.generated.ts',
      'apps/wallet-service/src/core/config/known-public-secrets.generated.ts',
      'apps/worker/src/known-public-secrets.generated.ts',
      'apps/realtime-gateway/src/known-public-secrets.generated.ts',
    ].map((p) => readFileSync(resolve(root, p), 'utf8'));
    for (const c of copies) expect(c).toBe(copies[0]);
  });
});
